const originalTitle=document.title;
const revisionText={"DE": {"Traemos a Suiza una selección de sabores españoles con un servicio cercano y personal. Autenticidad, calidad y tradición española: esa es la esencia de Almazara.": "Wir bringen eine Auswahl spanischer Spezialitäten in die Schweiz und bieten einen persönlichen, nahen Service. Authentizität, Qualität und spanische Tradition: Das ist die Essenz von Almazara.", "“Del Mediterráneo al mundo, con el mismo compromiso de siempre.”": "„Vom Mittelmeer in die Welt – mit der gleichen Hingabe wie immer.“", "Aceite de oliva virgen extra nacido entre tradición y tiempo.": "Natives Olivenöl extra, geprägt von Tradition und Zeit.", "En Almazara seleccionamos productos que representan la esencia de la gastronomía española, con especial atención al Aceite de Oliva Virgen Extra y los jamones ibéricos. Respetamos el origen, el tiempo y los procesos tradicionales para ofrecer una selección cuidada y auténtica.": "Bei Almazara wählen wir Produkte aus, die das Wesen der spanischen Gastronomie verkörpern, insbesondere natives Olivenöl extra und Ibérico-Schinken. Mit Respekt vor Herkunft, Zeit und traditionellen Verfahren bieten wir eine sorgfältige, authentische Auswahl.", "Creemos que la verdadera calidad comienza en el origen. Apostamos por productos elaborados con respeto por la tierra, la tradición y las personas que hacen posible cada producto.": "Wir glauben, dass wahre Qualität beim Ursprung beginnt. Wir setzen auf Produkte, die mit Respekt vor der Erde, der Tradition und den Menschen hergestellt werden, die sie möglich machen.", "“Eres lo que comes.”": "„Du bist, was du isst.“", "Tradición": "Tradition", "Origen": "Herkunft", "Raíces mediterráneas": "Mediterrane Wurzeln", "Producto premium": "Premiumprodukt", "Servicio y cercanía": "Persönlicher Service", "EL ORO DE": "DAS GOLD", "NUESTRA TIERRA": "UNSERER ERDE", "PRODUCTOS": "PRODUKTE", "PACKS GOURMET": "GOURMET-PAKETE", "Aceites de oliva": "Olivenöle", "Jamones ibéricos": "Ibérico-Schinken", "Packs gourmet": "Gourmet-Pakete", "PRECIO MÁXIMO (CHF)": "HÖCHSTPREIS (CHF)", "VER TODOS": "ALLE ANZEIGEN", "No hay productos que coincidan con estos filtros.": "Keine Produkte entsprechen diesen Filtern."}, "FR": {"Traemos a Suiza una selección de sabores españoles con un servicio cercano y personal. Autenticidad, calidad y tradición española: esa es la esencia de Almazara.": "Nous apportons en Suisse une sélection de saveurs espagnoles avec un service proche et personnalisé. Authenticité, qualité et tradition espagnole : telle est l’essence d’Almazara.", "“Del Mediterráneo al mundo, con el mismo compromiso de siempre.”": "« De la Méditerranée au monde, avec le même engagement depuis toujours. »", "Aceite de oliva virgen extra nacido entre tradición y tiempo.": "Une huile d’olive vierge extra née de la tradition et du temps.", "En Almazara seleccionamos productos que representan la esencia de la gastronomía española, con especial atención al Aceite de Oliva Virgen Extra y los jamones ibéricos. Respetamos el origen, el tiempo y los procesos tradicionales para ofrecer una selección cuidada y auténtica.": "Chez Almazara, nous sélectionnons des produits qui incarnent la gastronomie espagnole, notamment l’huile d’olive vierge extra et les jambons ibériques. Nous respectons l’origine, le temps et les méthodes traditionnelles pour proposer une sélection soignée et authentique.", "Creemos que la verdadera calidad comienza en el origen. Apostamos por productos elaborados con respeto por la tierra, la tradición y las personas que hacen posible cada producto.": "Nous croyons que la vraie qualité commence à l’origine. Nous choisissons des produits élaborés dans le respect de la terre, des traditions et des personnes qui les rendent possibles.", "“Eres lo que comes.”": "« Vous êtes ce que vous mangez. »", "Tradición": "Tradition", "Origen": "Origine", "Raíces mediterráneas": "Racines méditerranéennes", "Producto premium": "Produit premium", "Servicio y cercanía": "Service de proximité", "EL ORO DE": "L’OR DE", "NUESTRA TIERRA": "NOTRE TERRE", "PRODUCTOS": "PRODUITS", "PACKS GOURMET": "COFFRETS GOURMET", "Aceites de oliva": "Huiles d’olive", "Jamones ibéricos": "Jambons ibériques", "Packs gourmet": "Coffrets gourmet", "PRECIO MÁXIMO (CHF)": "PRIX MAXIMUM (CHF)", "VER TODOS": "TOUT VOIR", "No hay productos que coincidan con estos filtros.": "Aucun produit ne correspond à ces filtres."}, "IT": {"Traemos a Suiza una selección de sabores españoles con un servicio cercano y personal. Autenticidad, calidad y tradición española: esa es la esencia de Almazara.": "Portiamo in Svizzera una selezione di sapori spagnoli con un servizio attento e personale. Autenticità, qualità e tradizione spagnola: questa è l’essenza di Almazara.", "“Del Mediterráneo al mundo, con el mismo compromiso de siempre.”": "“Dal Mediterraneo al mondo, con lo stesso impegno di sempre.”", "Aceite de oliva virgen extra nacido entre tradición y tiempo.": "Olio extravergine d’oliva nato dalla tradizione e dal tempo.", "En Almazara seleccionamos productos que representan la esencia de la gastronomía española, con especial atención al Aceite de Oliva Virgen Extra y los jamones ibéricos. Respetamos el origen, el tiempo y los procesos tradicionales para ofrecer una selección cuidada y auténtica.": "In Almazara selezioniamo prodotti che esprimono l’essenza della gastronomia spagnola, in particolare olio extravergine d’oliva e prosciutti iberici. Rispettiamo l’origine, il tempo e i metodi tradizionali per offrire una selezione curata e autentica.", "Creemos que la verdadera calidad comienza en el origen. Apostamos por productos elaborados con respeto por la tierra, la tradición y las personas que hacen posible cada producto.": "Crediamo che la vera qualità inizi dall’origine. Scegliamo prodotti realizzati nel rispetto della terra, della tradizione e delle persone che li rendono possibili.", "“Eres lo que comes.”": "“Sei quello che mangi.”", "Tradición": "Tradizione", "Origen": "Origine", "Raíces mediterráneas": "Radici mediterranee", "Producto premium": "Prodotto premium", "Servicio y cercanía": "Servizio e vicinanza", "EL ORO DE": "L’ORO DELLA", "NUESTRA TIERRA": "NOSTRA TERRA", "PRODUCTOS": "PRODOTTI", "PACKS GOURMET": "CONFEZIONI GOURMET", "Aceites de oliva": "Oli d’oliva", "Jamones ibéricos": "Prosciutti iberici", "Packs gourmet": "Confezioni gourmet", "PRECIO MÁXIMO (CHF)": "PREZZO MASSIMO (CHF)", "VER TODOS": "VEDI TUTTI", "No hay productos que coincidan con estos filtros.": "Nessun prodotto corrisponde a questi filtri."}, "EN": {"Traemos a Suiza una selección de sabores españoles con un servicio cercano y personal. Autenticidad, calidad y tradición española: esa es la esencia de Almazara.": "We bring a selection of Spanish flavours to Switzerland with friendly, personal service. Authenticity, quality and Spanish tradition: that is the essence of Almazara.", "“Del Mediterráneo al mundo, con el mismo compromiso de siempre.”": "“From the Mediterranean to the world, with the same commitment as always.”", "Aceite de oliva virgen extra nacido entre tradición y tiempo.": "Extra virgin olive oil born of tradition and time.", "En Almazara seleccionamos productos que representan la esencia de la gastronomía española, con especial atención al Aceite de Oliva Virgen Extra y los jamones ibéricos. Respetamos el origen, el tiempo y los procesos tradicionales para ofrecer una selección cuidada y auténtica.": "At Almazara, we select products that capture the essence of Spanish cuisine, especially extra virgin olive oil and Iberian hams. We respect their origin, time and traditional methods to offer a carefully chosen, authentic selection.", "Creemos que la verdadera calidad comienza en el origen. Apostamos por productos elaborados con respeto por la tierra, la tradición y las personas que hacen posible cada producto.": "We believe true quality begins at the source. We choose products made with respect for the land, tradition and the people behind each one.", "“Eres lo que comes.”": "“You are what you eat.”", "Tradición": "Tradition", "Origen": "Origin", "Raíces mediterráneas": "Mediterranean roots", "Producto premium": "Premium product", "Servicio y cercanía": "Personal service", "EL ORO DE": "THE GOLD OF", "NUESTRA TIERRA": "OUR LAND", "PRODUCTOS": "PRODUCTS", "PACKS GOURMET": "GOURMET PACKS", "Aceites de oliva": "Olive oils", "Jamones ibéricos": "Iberian hams", "Packs gourmet": "Gourmet packs", "PRECIO MÁXIMO (CHF)": "MAXIMUM PRICE (CHF)", "VER TODOS": "VIEW ALL", "No hay productos que coincidan con estos filtros.": "No products match these filters."}};
Object.entries(revisionText).forEach(([lang,strings])=>Object.assign(PAGE_TEXT[lang],strings));

function applyPageText(lang){
 const map=PAGE_TEXT[lang]||{};
 const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode(n){if(!n.parentElement||['SCRIPT','STYLE','OPTION'].includes(n.parentElement.tagName)||n.parentElement.closest('.site-header,.mobile-nav-panel,.site-footer,.home-hero,.values,.home-products-premium,.home-story-content,.feature-grid-home-final,.cart-drawer,.search-premium,.catalog-count,.checkout-wrap,.legal-main,.legal-document-nav,.legal-checkout-footer,.contact-privacy,.alma-assistant,.oil-detail-main,.product-modal,.newsletter-success,.form-result,.checkout-result,.almazara-intro'))return NodeFilter.FILTER_REJECT;return n.nodeValue.trim()?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT}});
 const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
 nodes.forEach(n=>{if(n.__es==null)n.__es=n.nodeValue;const raw=n.__es,trim=raw.trim();const v=map[trim];if(v!=null)n.nodeValue=raw.replace(trim,v);else n.nodeValue=raw;});
 document.querySelectorAll('input[placeholder],textarea[placeholder]').forEach(el=>{if(el.dataset.esPlaceholder==null)el.dataset.esPlaceholder=el.placeholder;const v=map[el.dataset.esPlaceholder];el.placeholder=(lang==='ES'?el.dataset.esPlaceholder:(v||el.dataset.esPlaceholder));});
 document.querySelectorAll('.origin-story img, .origin-process img, .origin-process video, .origin-suppliers video, img[src*="/proveedores/"], .oil-product-media img').forEach(el=>{
  ['alt','aria-label'].forEach(attr=>{
   if(!el.hasAttribute(attr))return;
   const key='data-es-'+attr;
   if(!el.hasAttribute(key))el.setAttribute(key,el.getAttribute(attr));
   const source=el.getAttribute(key);
   el.setAttribute(attr,map[source]||source);
  });
 });
 const page=document.body.className||''; const titles={DE:{'nosotros.html':'Über uns · ALMAZARA','aceites.html':'Olivenöle · ALMAZARA','jamones.html':'Schinken · ALMAZARA','productos.html':'Produkte · ALMAZARA','recetas.html':'Rezepte · ALMAZARA','contacto.html':'Kontakt · ALMAZARA'},EN:{'nosotros.html':'About us · ALMAZARA','aceites.html':'Olive oils · ALMAZARA','jamones.html':'Hams · ALMAZARA','productos.html':'Products · ALMAZARA','recetas.html':'Recipes · ALMAZARA','contacto.html':'Contact · ALMAZARA'},FR:{'nosotros.html':'À propos · ALMAZARA','aceites.html':'Huiles · ALMAZARA','jamones.html':'Jambons · ALMAZARA','productos.html':'Produits · ALMAZARA','recetas.html':'Recettes · ALMAZARA','contacto.html':'Contact · ALMAZARA'},IT:{'nosotros.html':'Chi siamo · ALMAZARA','aceites.html':'Oli · ALMAZARA','jamones.html':'Prosciutti · ALMAZARA','productos.html':'Prodotti · ALMAZARA','recetas.html':'Ricette · ALMAZARA','contacto.html':'Contatti · ALMAZARA'}};
 const fn=location.pathname.split('/').pop()||'index.html'; if(lang==='ES')document.title=originalTitle; if(lang!=='ES'&&titles[lang]&&titles[lang][fn])document.title=titles[lang][fn];
}
document.addEventListener('almazara:languagechange',e=>apply(e.detail.lang));document.addEventListener('DOMContentLoaded',()=>apply(localStorage.getItem('almazara-lang')||'ES'));window.AlmazaraI18n={apply,translate:(text,lang)=>((PAGE_TEXT[String(lang||localStorage.getItem('almazara-lang')||'ES').toUpperCase()]||{})[text]||text)};
